export const getVerifyAdminPasswordUrl = () => {
  return `/api/auth/verify`;
};

export const verifyAdminPassword = async (
  adminAuthInput: AdminAuthInput,
  options?: RequestInit,
): Promise<AdminAuthResult> => {
  return customFetch<AdminAuthResult>(getVerifyAdminPasswordUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(adminAuthInput),
  });
};

export const getVerifyAdminPasswordMutationOptions = <
  TError = ErrorType<void>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof verifyAdminPassword>>,
    TError,
    { data: BodyType<AdminAuthInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof verifyAdminPassword>>,
  TError,
  { data: BodyType<AdminAuthInput> },
  TContext
> => {
  const mutationKey = ["verifyAdminPassword"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof verifyAdminPassword>>,
    { data: BodyType<AdminAuthInput> }
  > = (props) => {
    const { data } = props ?? {};

    return verifyAdminPassword(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type VerifyAdminPasswordMutationResult = NonNullable<
  Awaited<ReturnType<typeof verifyAdminPassword>>
>;
export type VerifyAdminPasswordMutationBody = BodyType<AdminAuthInput>;
